1	@page "/grants"
2	@using Microsoft.EntityFrameworkCore
3	@attribute [Authorize]
4	@rendermode @(new InteractiveServerRenderMode(prerender: false))
5	@inject IDbContextFactory<GatekeeperDbContext> DbFactory
6	@inject IAuditLogger Audit
7	
8	<PageTitle>Gatekeeper · Grants</PageTitle>
9	
10	<h1>Grants</h1>
11	<p class="text-muted">An allow or deny of a permission on a resource, attached to either a user or a role.</p>
12	
13	<div class="card mb-4">
14	    <div class="card-header">Add grant</div>
15	    <div class="card-body">
16	        <EditForm Model="form" OnValidSubmit="AddAsync">
17	            <DataAnnotationsValidator />
18	            <div class="row g-2 align-items-end">
19	                <div class="col-md-3">
20	                    <label class="form-label">Customer</label>
21	                    <InputSelect class="form-select" @bind-Value="form.CustomerId" @bind-Value:after="OnCustomerChanged">
22	                        <option value="">— select —</option>
23	                        @foreach (var c in customers)
24	                        {
25	                            <option value="@c.Id">@c.Name</option>
26	                        }
27	                    </InputSelect>
28	                    <ValidationMessage For="() => form.CustomerId" />
29	                </div>
30	                <div class="col-md-2">
31	                    <label class="form-label">Effect</label>
32	                    <InputSelect class="form-select" @bind-Value="form.Effect">
33	                        @foreach (var e in Enum.GetValues<GrantEffect>())
34	                        {
35	                            <option value="@e">@e</option>
36	                        }
37	                    </InputSelect>
38	                </div>
39	                <div class="col-md-3">
40	                    <label class="form-label">Permission</label>
41	                    <InputText class="form-control" placeholder="e.g. documents.read" @bind-Value="form.Permission" />
42	                    <ValidationMessage For="() => form.Permission" />
43	                </div>
44	                <div class="col-md-2">
45	                    <label class="form-label">Resource</label>
46	                    <InputText class="form-control" placeholder="* or project:42" @bind-Value="form.Resource" />
47	                    <ValidationMessage For="() => form.Resource" />
48	                </div>
49	                <div class="col-md-2">
50	                    <label class="form-label">Subject type</label>
51	                    <InputSelect class="form-select" @bind-Value="form.SubjectType" @bind-Value:after="OnSubjectTypeChanged">
52	                        <option value="@GrantSubjectType.Role">Role</option>
53	                        <option value="@GrantSubjectType.User">User</option>
54	                    </InputSelect>
55	                </div>
56	            </div>
57	            <div class="row g-2 align-items-end mt-1">
58	                <div class="col-md-4">
59	                    <label class="form-label">Subject</label>
60	                    @if (form.SubjectType == GrantSubjectType.Role)
61	                    {
62	                        <InputSelect class="form-select" @bind-Value="form.RoleId">
63	                            <option value="">— select role —</option>
64	                            @foreach (var r in scopedRoles)
65	                            {
66	                                <option value="@r.Id">@r.Name</option>
67	                            }
68	                        </InputSelect>
69	                    }
70	                    else
71	                    {
72	                        <InputSelect class="form-select" @bind-Value="form.UserId">
73	                            <option value="">— select user —</option>
74	                            @foreach (var u in scopedUsers)
75	                            {
76	                                <option value="@u.Id">@u.Email</option>
77	                            }
78	                        </InputSelect>
79	                    }
80	                </div>
81	                <div class="col-md-3">
82	                    <button type="submit" class="btn btn-primary">Add grant</button>
83	                </div>
84	            </div>
85	        </EditForm>
86	        @if (message is not null)
87	        {
88	            <div class="alert @(isError ? "alert-danger" : "alert-info") mt-3 mb-0 py-2">@message</div>
89	        }
90	    </div>
91	</div>
92	
93	@if (grants is null)
94	{
95	    <p><em>Loading…</em></p>
96	}
97	else if (grants.Count == 0)
98	{
99	    <p>No grants yet.</p>
100	}
101	else
102	{
103	    <table class="table table-hover align-middle">
104	        <thead>
105	            <tr><th>Effect</th><th>Permission</th><th>Resource</th><th>Subject</th><th>Customer</th><th class="text-end">Actions</th></tr>
106	        </thead>
107	        <tbody>
108	            @foreach (var g in grants)
109	            {
110	                <tr>
111	                    <td><span class="badge @(g.Effect == GrantEffect.Allow ? "bg-success" : "bg-danger")">@g.Effect</span></td>
112	                    <td><code>@g.Permission</code></td>
113	                    <td><code>@g.Resource</code></td>
114	                    <td>
115	                        @if (g.RoleId is not null)
116	                        {
117	                            <span class="badge bg-info text-dark">role</span> @g.Role?.Name
118	                        }
119	                        else
120	                        {
121	                            <span class="badge bg-warning text-dark">user</span> @g.User?.Email
122	                        }
123	                    </td>
124	                    <td>@g.Customer?.Name</td>
125	                    <td class="text-end">
126	                        <button class="btn btn-sm btn-outline-danger" @onclick="() => DeleteAsync(g)">Delete</button>
127	                    </td>
128	                </tr>
129	            }
130	        </tbody>
131	    </table>
132	}
133	
134	@code {
135	    private List<Grant>? grants;
136	    private List<Customer> customers = new();
137	    private List<Role> scopedRoles = new();
138	    private List<ApplicationUser> scopedUsers = new();
139	    private string? message;
140	    private bool isError;
141	
142	    private GrantForm form = new();
143	
144	    public class GrantForm
145	    {
146	        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Pick a customer.")]
147	        public Guid? CustomerId { get; set; }
148	        public GrantEffect Effect { get; set; } = GrantEffect.Allow;
149	        [System.ComponentModel.DataAnnotations.Required]
150	        [System.ComponentModel.DataAnnotations.StringLength(200)]
151	        public string Permission { get; set; } = string.Empty;
152	        [System.ComponentModel.DataAnnotations.Required]
153	        [System.ComponentModel.DataAnnotations.StringLength(200)]
154	        public string Resource { get; set; } = "*";
155	        public GrantSubjectType SubjectType { get; set; } = GrantSubjectType.Role;
156	        public Guid? RoleId { get; set; }
157	        public string? UserId { get; set; }
158	    }
159	
160	    protected override Task OnInitializedAsync() => LoadAsync();
161	
162	    private async Task LoadAsync()
163	    {
164	        await using var db = await DbFactory.CreateDbContextAsync();
165	        customers = await db.Customers.OrderBy(c => c.Name).ToListAsync();
166	        grants = await db.Grants
167	            .Include(g => g.Customer)
168	            .Include(g => g.Role)
169	            .Include(g => g.User)
170	            .OrderByDescending(g => g.CreatedAt)
171	            .ToListAsync();
172	        await RefreshSubjectsAsync(db);
173	    }
174	
175	    private async Task OnCustomerChanged()
176	    {
177	        form.RoleId = null;
178	        form.UserId = null;
179	        await using var db = await DbFactory.CreateDbContextAsync();
180	        await RefreshSubjectsAsync(db);
181	    }
182	
183	    private void OnSubjectTypeChanged()
184	    {
185	        form.RoleId = null;
186	        form.UserId = null;
187	    }
188	
189	    private async Task RefreshSubjectsAsync(GatekeeperDbContext db)
190	    {
191	        if (form.CustomerId is null)
192	        {
193	            scopedRoles = new();
194	            scopedUsers = new();
195	            return;
196	        }
197	        scopedRoles = await db.Roles.Where(r => r.CustomerId == form.CustomerId).OrderBy(r => r.Name).ToListAsync();
198	        scopedUsers = await db.Users.Where(u => u.CustomerId == form.CustomerId).OrderBy(u => u.Email).ToListAsync();
199	    }
200	
201	    private async Task AddAsync()
202	    {
203	        isError = false;
204	        message = null;
205	
206	        if (form.SubjectType == GrantSubjectType.Role && form.RoleId is null)
207	        {
208	            isError = true; message = "Pick a role for the grant."; return;
209	        }
210	        if (form.SubjectType == GrantSubjectType.User && string.IsNullOrEmpty(form.UserId))
211	        {
212	            isError = true; message = "Pick a user for the grant."; return;
213	        }
214	
215	        var grant = new Grant
216	        {
217	            CustomerId = form.CustomerId!.Value,
218	            Effect = form.Effect,
219	            Permission = form.Permission.Trim(),
220	            Resource = string.IsNullOrWhiteSpace(form.Resource) ? "*" : form.Resource.Trim(),
221	            RoleId = form.SubjectType == GrantSubjectType.Role ? form.RoleId : null,
222	            UserId = form.SubjectType == GrantSubjectType.User ? form.UserId : null,
223	        };
224	
225	        await using var db = await DbFactory.CreateDbContextAsync();
226	        db.Grants.Add(grant);
227	        await db.SaveChangesAsync();
228	        await Audit.LogAsync("Created", "Grant", grant.Id.ToString(),
229	            $"{grant.Effect} '{grant.Permission}' on '{grant.Resource}' for {form.SubjectType.ToString().ToLower()}", grant.CustomerId);
230	
231	        message = "Grant added.";
232	        var keepCustomer = form.CustomerId;
233	        var keepType = form.SubjectType;
234	        form = new GrantForm { CustomerId = keepCustomer, SubjectType = keepType };
235	        await LoadAsync();
236	    }
237	
238	    private async Task DeleteAsync(Grant g)
239	    {
240	        await using var db = await DbFactory.CreateDbContextAsync();
241	        var existing = await db.Grants.FindAsync(g.Id);
242	        if (existing is not null)
243	        {
244	            db.Grants.Remove(existing);
245	            await db.SaveChangesAsync();
246	            await Audit.LogAsync("Deleted", "Grant", g.Id.ToString(),
247	                $"Removed {existing.Effect} '{existing.Permission}' on '{existing.Resource}'", existing.CustomerId);
248	            message = "Grant deleted.";
249	            isError = false;
250	        }
251	        await LoadAsync();
252	    }
253	}
